    {
        var baseText = _baseUrl.AbsoluteUri.TrimEnd('/') + "/" + path.TrimStart('/');
        var queryText = string.Join("&", query.Select(item => item.Key + "=" + item.Value));
        return new Uri(queryText.Length == 0 ? baseText : baseText + "?" + queryText,
            UriKind.Absolute);
    }

    private static string Escape(string value, bool allowReserved)
    {
        var encoded = Uri.EscapeDataString(value);
        if (!allowReserved) return encoded;
        foreach (var item in ReservedEscapes)
            encoded = encoded.Replace(item, Uri.UnescapeDataString(item), StringComparison.OrdinalIgnoreCase);
        return encoded;
    }

    private static JsonElement ToElement(object value)
        => value is JsonElement element ? element : JsonSerializer.SerializeToElement(value, value.GetType(), JsonOptions);

    private static string ElementText(JsonElement element) => element.ValueKind switch
    {
        JsonValueKind.String => element.GetString() ?? "",
        JsonValueKind.True => "true",
        JsonValueKind.False => "false",
        JsonValueKind.Null or JsonValueKind.Undefined => "",
        JsonValueKind.Array => string.Join(",", ElementItems(element)),
        JsonValueKind.Object => string.Join(",", ElementPairs(element).SelectMany(pair => new[] { pair.Key, pair.Value })),
        _ => element.GetRawText(),
    };

    private static List<string> ElementItems(JsonElement element)
        => element.EnumerateArray().Select(ElementText).ToList();

    private static List<KeyValuePair<string, string>> ElementPairs(JsonElement element)
        => element.EnumerateObject().Select(property => new KeyValuePair<string, string>(property.Name, ElementText(property.Value))).ToList();

    private static string JsonText(object value)
        => JsonSerializer.Serialize(value, value.GetType(), JsonOptions);

    private static string ToWire(object value) => ElementText(ToElement(value));

    private static void AppendQuery(List<KeyValuePair<string, string>> query, string name, object value,
        string style, bool explode, bool allowReserved)
    {
        var element = ToElement(value);
        var key = Escape(name, false);
        var separator = style switch { "spaceDelimited" => "%20", "pipeDelimited" => "%7C", _ => "," };
        switch (element.ValueKind)
        {
            case JsonValueKind.Array:
                var items = ElementItems(element);
                if (explode && style is "form" or "spaceDelimited" or "pipeDelimited")
                    foreach (var item in items) query.Add(new(key, Escape(item, allowReserved)));
                else
                    query.Add(new(key, string.Join(separator, items.Select(item => Escape(item, allowReserved)))));
                break;
            case JsonValueKind.Object:
                var pairs = ElementPairs(element);
                if (style == "deepObject")
                    foreach (var pair in pairs)
                        query.Add(new(key + "%5B" + Escape(pair.Key, false) + "%5D", Escape(pair.Value, allowReserved)));
                else if (explode)
                    foreach (var pair in pairs) query.Add(new(Escape(pair.Key, false), Escape(pair.Value, allowReserved)));
                else
                    query.Add(new(key, string.Join(separator, pairs.SelectMany(pair =>
                        new[] { Escape(pair.Key, allowReserved), Escape(pair.Value, allowReserved) }))));
                break;
            case JsonValueKind.Null:
            case JsonValueKind.Undefined:
                break;
            default:
                query.Add(new(key, Escape(ElementText(element), allowReserved)));
                break;
        }
    }

    private static string PathValue(string name, object value, string style, bool explode, bool allowReserved)
    {
        var element = ToElement(value);
        string Enc(string text) => Escape(text, allowReserved);
        var prefix = style switch { "label" => ".", "matrix" => ";", _ => "" };
        switch (element.ValueKind)
        {
            case JsonValueKind.Array:
                var items = ElementItems(element).Select(Enc).ToList();
                if (style == "matrix")
                    return explode
                        ? string.Concat(items.Select(item => ";" + Enc(name) + "=" + item))
                        : ";" + Enc(name) + "=" + string.Join(",", items);
                return prefix + string.Join(style == "label" && explode ? "." : ",", items);
            case JsonValueKind.Object:
                var pairs = ElementPairs(element);
                if (style == "matrix")
                    return explode
                        ? string.Concat(pairs.Select(pair => ";" + Enc(pair.Key) + "=" + Enc(pair.Value)))
                        : ";" + Enc(name) + "=" + string.Join(",", pairs.SelectMany(pair => new[] { Enc(pair.Key), Enc(pair.Value) }));
                if (explode)
                    return prefix + string.Join(style == "label" ? "." : ",", pairs.Select(pair => Enc(pair.Key) + "=" + Enc(pair.Value)));
                return prefix + string.Join(",", pairs.SelectMany(pair => new[] { Enc(pair.Key), Enc(pair.Value) }));
            default:
                var text = Enc(ElementText(element));
                return style == "matrix" ? ";" + Enc(name) + "=" + text : prefix + text;
        }
    }

    private static string HeaderValue(object value, bool explode)
    {
        var element = ToElement(value);
        if (element.ValueKind == JsonValueKind.Object && explode)
            return string.Join(",", ElementPairs(element).Select(pair => pair.Key + "=" + pair.Value));
        return ElementText(element);
    }

    private static HttpContent JsonBody(object body, string mediaType)
    {
        var content = new ByteArrayContent(JsonSerializer.SerializeToUtf8Bytes(body, body.GetType(), JsonOptions));
        content.Headers.ContentType = MediaTypeHeaderValue.Parse(mediaType);
        return content;
    }

    private static HttpContent BinaryBody(byte[] body, string mediaType)
    {
        var content = new ByteArrayContent(body);
        content.Headers.ContentType = MediaTypeHeaderValue.Parse(mediaType);
        return content;
    }

    private static HttpContent TextBody(string body, string mediaType)
        => new StringContent(body, Encoding.UTF8, mediaType);

    private static HttpContent FormBody(List<KeyValuePair<string, string>> pairs)
        => new FormUrlEncodedContent(pairs);

    private static void AddJsonPart<T>(MultipartFormDataContent form, string name, T value, string? contentType)
    {
        var part = new ByteArrayContent(JsonSerializer.SerializeToUtf8Bytes(value, typeof(T), JsonOptions));
        part.Headers.ContentType = MediaTypeHeaderValue.Parse(contentType ?? "application/json");
        form.Add(part, name);
    }

    private static void AddTextPart(MultipartFormDataContent form, string name, string value, string? contentType)
    {
        var part = new StringContent(value, Encoding.UTF8, contentType ?? "text/plain");
        form.Add(part, name);
    }

    private static void AddFilePart(MultipartFormDataContent form, string name, FilePart value, string? contentType)
    {
        var part = value.ToContent();
        if (contentType is not null && value.ContentType is null) part.Headers.ContentType = MediaTypeHeaderValue.Parse(contentType);
        form.Add(part, name, value.FileName ?? name);
    }

    private static void AddBytesPart(MultipartFormDataContent form, string name, byte[] value, string? contentType)
    {
        var part = new ByteArrayContent(value);
        part.Headers.ContentType = MediaTypeHeaderValue.Parse(contentType ?? "application/octet-stream");
        form.Add(part, name, name);
    }

    private static void AddElementParts(MultipartFormDataContent form, JsonElement body)
    {
        if (body.ValueKind != JsonValueKind.Object) return;
        foreach (var property in body.EnumerateObject())
        {
            if (property.Value.ValueKind is JsonValueKind.Object or JsonValueKind.Array)
                AddJsonPart(form, property.Name, property.Value, null);
            else if (property.Value.ValueKind is not (JsonValueKind.Null or JsonValueKind.Undefined))
                AddTextPart(form, property.Name, ElementText(property.Value), null);
        }
    }

    private static void AddFormField(List<KeyValuePair<string, string>> pairs, string? name, JsonElement value)
    {
        switch (value.ValueKind)
        {
            case JsonValueKind.Null:
            case JsonValueKind.Undefined:
                return;
            case JsonValueKind.Array when name is not null:
                foreach (var item in value.EnumerateArray()) pairs.Add(new(name, ElementText(item)));
                return;
            case JsonValueKind.Object when name is null:
                foreach (var property in value.EnumerateObject()) AddFormField(pairs, property.Name, property.Value);
                return;
            case JsonValueKind.Object:
                pairs.Add(new(name!, value.GetRawText()));
                return;
            default:
                pairs.Add(new(name ?? "value", ElementText(value)));
                return;
        }
    }

    private void ApplyAuthentication(Dictionary<string, string> headers,
        List<KeyValuePair<string, string>> query, Dictionary<string, string> cookies,
        string[][] alternatives, string operation)
    {
        if (alternatives.Length == 0) return;
        foreach (var alternative in alternatives)
        {
            var resolved = new List<(AuthScheme Scheme, string? Value)>();
            var valid = true;
            foreach (var name in alternative)
            {
                if (!AuthSchemes.TryGetValue(name, out var scheme)) { valid = false; break; }
                var value = Credential(name, scheme);
                if (value is null && scheme.Type != "mutualTLS") { valid = false; break; }
                resolved.Add((scheme, value));
            }
            if (!valid) continue;
            foreach (var item in resolved)
            {
                var scheme = item.Scheme;
                var value = item.Value;
                if (scheme.Type == "apiKey")
                {
                    if (scheme.Location == "query") query.Add(new(Escape(scheme.Name!, false), Escape(value!, false)));
                    else if (scheme.Location == "cookie") cookies[scheme.Name!] = value!;
                    else headers[scheme.Name!] = value!;
                }
                else if (scheme.Type is "oauth2" or "openIdConnect" ||
                    scheme.Type == "http" && string.Equals(scheme.Scheme, "bearer", StringComparison.OrdinalIgnoreCase))
                    headers["Authorization"] = "Bearer " + value;
                else if (scheme.Type == "http" && string.Equals(scheme.Scheme, "basic", StringComparison.OrdinalIgnoreCase))
                    headers["Authorization"] = "Basic " + Convert.ToBase64String(Encoding.UTF8.GetBytes(value!));
            }
            return;
        }
        throw new MissingCredentialsException("No configured credential satisfies this operation.", operation);
    }

    private string? Credential(string name, AuthScheme scheme)
    {
        if (_options.Auth.TryGetValue(name, out var value)) return value;
        if (scheme.Type == "apiKey") return _options.ApiKey;
        if (scheme.Type is "oauth2" or "openIdConnect" ||
            scheme.Type == "http" && string.Equals(scheme.Scheme, "bearer", StringComparison.OrdinalIgnoreCase))
            return _options.AccessToken;
        if (scheme.Type == "http" && string.Equals(scheme.Scheme, "basic", StringComparison.OrdinalIgnoreCase)
            && _options.Username is not null) return _options.Username + ":" + (_options.Password ?? "");
        return null;
    }

    private static void SetHeader(HttpRequestMessage request, string name, string value)
    {
        request.Headers.Remove(name);
        if (!request.Headers.TryAddWithoutValidation(name, value) && request.Content is not null)
        {
            request.Content.Headers.Remove(name);
            request.Content.Headers.TryAddWithoutValidation(name, value);
        }
    }

    /// <summary>Dispose the owned <see cref="HttpClient"/>, if any.</summary>
    public void Dispose()
    {
        if (_ownsClient) _httpClient.Dispose();
    }
}
